import{_ as e,o as a,c as r,aj as d}from"./chunks/framework.Dp4IQB_f.js";const u=JSON.parse('{"title":"Compared with other libraries","description":"","frontmatter":{},"headers":[],"relativePath":"guide/benchmarks.md","filePath":"guide/benchmarks.md"}'),s={name:"guide/benchmarks.md"};function o(i,t,n,h,l,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="compared-with-other-libraries" tabindex="-1">Compared with other libraries <a class="header-anchor" href="#compared-with-other-libraries" aria-label="Permalink to &quot;Compared with other libraries&quot;">​</a></h1><p>Measured with <code>npm run bench:versus</code> on public data (Spotify song titles, the 20,000 most common English words), Node 22, median of 7 runs. Every library gets the same inputs.</p><h2 id="string-similarity" tabindex="-1">string-similarity <a class="header-anchor" href="#string-similarity" aria-label="Permalink to &quot;string-similarity&quot;">​</a></h2><p><code>fuzzy-toolkit/string-similarity</code> returns exactly the same numbers as <code>string-similarity</code> (checked on 20,000 real pairs and thousands of random ones in the tests).</p><table tabindex="0"><thead><tr><th>Task</th><th>string-similarity</th><th>fuzzy-toolkit</th><th></th></tr></thead><tbody><tr><td><code>compareTwoStrings</code>, 20,000 title pairs</td><td>47 ms</td><td>22 ms</td><td><strong>2.2× faster</strong></td></tr><tr><td><code>findBestMatch</code>, 1,000 queries × 2,000 titles</td><td>4.0 s</td><td>1.1 s</td><td><strong>3.5× faster</strong></td></tr></tbody></table><h2 id="did-you-mean" tabindex="-1">&quot;Did you mean…?&quot; <a class="header-anchor" href="#did-you-mean" aria-label="Permalink to &quot;&quot;Did you mean…?&quot;&quot;">​</a></h2><p>500 misspelled words against the 20,000 most common English words.</p><table tabindex="0"><thead><tr><th></th><th>Right word</th><th>Time</th></tr></thead><tbody><tr><td>string-similarity <code>findBestMatch</code></td><td>35.6 %</td><td>6.7 s</td></tr><tr><td>fuzzy-toolkit <code>createIndex(words).closest()</code></td><td><strong>94.8 %</strong></td><td><strong>0.96 s</strong></td></tr></tbody></table><h2 id="search-as-you-type" tabindex="-1">Search as you type <a class="header-anchor" href="#search-as-you-type" aria-label="Permalink to &quot;Search as you type&quot;">​</a></h2><p>300 typed queries (the start of a title, with a typo) over 23,450 song titles, top 10.</p><table tabindex="0"><thead><tr><th></th><th>Wanted title found</th><th>Time per query</th></tr></thead><tbody><tr><td>Fuse.js</td><td>75.3 %</td><td>71.6 ms</td></tr><tr><td>fuzzysort</td><td>23.7 %</td><td>0.7 ms</td></tr><tr><td>fuzzy-toolkit <code>createIndex(titles, { preset: &#39;search&#39; })</code></td><td><strong>89.0 %</strong></td><td>13.0 ms</td></tr></tbody></table><p>fuzzysort is the fastest but only matches letters in order, so a typo loses the result. fuzzy-toolkit finds more than Fuse.js, 5 times faster.</p><h2 id="levenshtein-distance" tabindex="-1">Levenshtein distance <a class="header-anchor" href="#levenshtein-distance" aria-label="Permalink to &quot;Levenshtein distance&quot;">​</a></h2><p>20,000 title pairs and 20,000 word pairs.</p><table tabindex="0"><thead><tr><th>fastest-levenshtein</th><th>fuzzy-toolkit <code>levenshtein</code></th></tr></thead><tbody><tr><td>17.1 ms</td><td><strong>12.6 ms</strong> (1.4× faster)</td></tr></tbody></table><h2 id="dedupe" tabindex="-1">Dedupe <a class="header-anchor" href="#dedupe" aria-label="Permalink to &quot;Dedupe&quot;">​</a></h2><p>5,000 song titles: 1.1 s with <code>dedupe()</code> (4.5 s in v2.1).</p>',17)])])}const p=e(s,[["render",o]]);export{u as __pageData,p as default};
